const msg = $json.messages?.[0];
if (!msg) {
  return [{ json: { messageText: '', from: '', isValid: false } }];
}
const text = msg.text?.body
  || msg.button?.text
  || msg.interactive?.button_reply?.title
  || msg.interactive?.list_reply?.title
  || '';
const from = msg.from || '';
const profileName = $json.contacts?.[0]?.profile?.name || '';
return [{
  json: {
    isValid: Boolean(text && from),
    messageText: text,
    from: from,
    profileName: profileName,
    waMessageId: msg.id || '',
    sessionId: from,
    timestamp: new Date().toISOString()
  }
}];

const sessionId = $json.sessionId;
const STATIC_TOKEN_BUDGET = 100000;
const stateKey = `token_state_${sessionId}`;

let tokenState = {
  totalTokensUsed: 0,
  tokensPerSession: STATIC_TOKEN_BUDGET,
  remainingTokens: STATIC_TOKEN_BUDGET,
  warningThreshold: STATIC_TOKEN_BUDGET * 0.10,
  isLow: false,
  lastCheckpoint: null,
  conversationHistory: []
};

try {
  const stored = await $getWorkflowStaticData('global');
  if (stored[stateKey]) {
    tokenState = stored[stateKey];
  }
} catch (e) {
  // Fresh start
}

return [{
  json: {
    ...tokenState,
    stateKey: stateKey,
    tokensRemaining: tokenState.tokensPerSession - tokenState.totalTokensUsed,
    isLow: (tokenState.tokensPerSession - tokenState.totalTokensUsed) <= tokenState.warningThreshold,
    isExhausted: (tokenState.tokensPerSession - tokenState.totalTokensUsed) <= 0
  }
}];

const sessionId = $json.sessionId || '';
const stateKey = `token_state_${sessionId}`;

const recoveredState = {
  totalTokensUsed: 0,
  tokensPerSession: 100000,
  warningThreshold: 10000,
  isLow: false,
  lastCheckpoint: {
    timestamp: new Date().toISOString(),
    message: 'Token budget reset. Conversation resumed from checkpoint.'
  },
  conversationHistory: []
};

try {
  const stored = await $getWorkflowStaticData('global');
  stored[stateKey] = recoveredState;
} catch (e) {
  // Static data unavailable
}

return [{
  json: {
    sessionId: sessionId,
    recovered: true,
    replyText: '⚠️ Token limit reached for this session. I\'ve saved our conversation checkpoint and reset. How can I help you?\n\nYour previous conversation is safely stored and will resume once the limit resets.'
  }
}];

const sessionId = $json.sessionId || '';
const stateKey = `token_state_${sessionId}`;
const messageText = $json.messageText || '';

let tokenState = {
  totalTokensUsed: 0,
  tokensPerSession: 100000,
  warningThreshold: 10000,
  isLow: false,
  lastCheckpoint: null,
  conversationHistory: []
};

try {
  const stored = await $getWorkflowStaticData('global');
  if (stored[stateKey]) {
    tokenState = stored[stateKey];
  }
} catch (e) {
  // Fresh state
}

// Estimate tokens: ~4 chars per token
const estimatedTokens = Math.ceil(messageText.length / 4);
let tokensUsed = tokenState.totalTokensUsed + estimatedTokens;

// Clamp to budget
const budget = tokenState.tokensPerSession;
if (tokensUsed > budget) tokensUsed = budget;

const remaining = budget - tokensUsed;
const isLow = remaining <= tokenState.warningThreshold;

// Save checkpoint every 5 messages
let history = tokenState.conversationHistory || [];
history.push({
  role: 'user',
  content: messageText,
  timestamp: new Date().toISOString()
});

if (history.length > 20) history = history.slice(-20);

let checkpoint = tokenState.lastCheckpoint;
if (history.length % 5 === 0) {
  checkpoint = {
    timestamp: new Date().toISOString(),
    messageCount: history.length,
    tokensUsed: tokensUsed,
    lastMessage: messageText
  };
}

const updatedState = {
  totalTokensUsed: tokensUsed,
  tokensPerSession: budget,
  warningThreshold: tokenState.warningThreshold,
  isLow: isLow,
  lastCheckpoint: checkpoint,
  conversationHistory: history
};

try {
  const stored = await $getWorkflowStaticData('global');
  stored[stateKey] = updatedState;
} catch (e) {
  // Static data unavailable
}

return [{
  json: {
    sessionId: sessionId,
    tokensUsed: tokensUsed,
    tokensRemaining: remaining,
    isLow: isLow,
    budget: budget,
    warningMessage: isLow ? `⚠️ Token usage at ${Math.round((tokensUsed/budget)*100)}%. ${remaining} tokens remaining.` : null,
    hasCheckpoint: checkpoint !== null
  }
}];

const sessionId = $json.sessionId || '';
const stateKey = `token_state_${sessionId}`;

let tokenState = {
  totalTokensUsed: 0,
  tokensPerSession: 100000,
  warningThreshold: 10000,
  isLow: false,
  lastCheckpoint: null,
  conversationHistory: []
};

try {
  const stored = await $getWorkflowStaticData('global');
  if (stored[stateKey]) {
    tokenState = stored[stateKey];
  }
} catch (e) {
  // Fresh state
}

const checkpoint = {
  timestamp: new Date().toISOString(),
  tokensUsed: tokenState.totalTokensUsed,
  tokensRemaining: tokenState.tokensPerSession - tokenState.totalTokensUsed,
  conversationSnapshot: (tokenState.conversationHistory || []).slice(-10)
};

tokenState.lastCheckpoint = checkpoint;

try {
  const stored = await $getWorkflowStaticData('global');
  stored[stateKey] = tokenState;
} catch (e) {
  // Static data unavailable
}

return [{
  json: {
    sessionId: sessionId,
    tokensUsed: tokenState.totalTokensUsed,
    tokensRemaining: checkpoint.tokensRemaining,
    warningMessage: `⚠️ Token usage at ${Math.round((tokenState.totalTokensUsed/tokenState.tokensPerSession)*100)}%. ${checkpoint.tokensRemaining} tokens left. Conversation checkpoint saved.`
  }
}];

let text = String($json.output || '').trim();
text = text.replace(/\*\*(.*?)\*\*/g, '*$1*');
if (text.length > 4000) text = text.slice(0, 3990) + '...';
return [{ json: { replyText: text } }];
